package com.luminor.tavernquest.domain.usecase.onboarding
import javax.inject.Inject
import com.luminor.tavernquest.core.time.DateProvider;import com.luminor.tavernquest.core.util.UuidProvider;import com.luminor.tavernquest.domain.model.*;import com.luminor.tavernquest.domain.repository.*
class CreateTavernUseCase @Inject constructor(private val taverns:TavernRepository,private val heroes:HeroRepository,private val settings:SettingsRepository,private val ids:UuidProvider,private val time:DateProvider){suspend operator fun invoke(name:String,emblem:TavernEmblem,description:String="",isPrivate:Boolean=true){val hero=heroes.get()?:error("Herói não criado");val tid=ids.newId();taverns.create(Tavern(tid,name.trim(),emblem,time.nowMillis(),description.trim(),isPrivate),TavernMember(ids.newId(),tid,hero.id,TavernRole.OWNER,time.nowMillis()));settings.setOnboardingCompleted(true)}}
